typedef struct {const char*s;char*d;size_t n;} A;
static void* w(void*p){A*a=p;const __m256i*s=(const __m256i*)a->s;__m256i*d=(__m256i*)a->d;size_t n=a->n/32;
for(size_t i=0;i<n;i++){_mm256_stream_si256(d+i,_mm256_xor_si256(_mm256_loadu_si256(s+i),_mm256_set1_epi8(1)));}return 0;}
void run(const char*s,char*d,size_t n,int t){pthread_t th[32];A a[32];size_t c=n/t/64*64;
for(int i=0;i<t;i++){a[i].s=s+i*c;a[i].d=d+i*c;a[i].n=(i==t-1)?n-i*c:c;pthread_create(&th[i],0,w,&a[i]);}
for(int i=0;i<t;i++)pthread_join(th[i],0);_mm_sfence();}
